        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "人間は変りはしない。ただ人間へ戻ってきたのだ。人間は堕落する。義士も聖女も堕落する。それを防ぐことはできないし、防ぐことによって人を救うことはできない。人間は生き、人間は堕ちる。そのこと以外の中に人間を救う便利な近道はない。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "人間だから堕ちるのであり、生きているから堕ちるだけだ。だが人間は永遠に堕ちぬくことはできないだろう。なぜなら人間の心は苦難に対して鋼鉄の如くでは有り得ない。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "堕落自体は常につまらぬものであり、悪であるにすぎないけれども、堕落のもつ性格の-つには孤独という偉大なる人間の実相が厳として存している。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "善人は気楽なもので、父母兄弟、人間共の虚しい義理や約束の上に安眠し、社会制度というものに全身を投げかけて平然として死んで行く。だが堕落者は常にそこからハミだして、ただ-人曠野を歩いて行くのである。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "悪徳はつまらぬものであるけれども、孤独という通路は神に通じる道であり、善人なおもて往生をとぐ、いわんや悪人をや、とはこの道だ。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "非論理が論理を圧倒するといふ微妙な人間関係は古来わが政治屋に珍重された処世術で、英雄豪傑の遺風であり、恰も土佐犬がテリヤを圧倒するかの如き非理智的な動物的人関係の-つである。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "負けいくさの戦争は全く小気味がいゝほど現実に幻想的だ。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "本当に礼節ある人間は戦争などやりたがる筈はない。人を敬うに、地にぬかずくような気違いであるから、まかり間違うと、腕ずくでアバレルほかにウサバラシができない。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "腕力と文明を混同するのがマチガイのもとである。原子バクダンだって鬼がふりまわすカナ棒の程度のもので、本当の文明文化はそれとはまるで違う。めいめいの豊かな生活だけが本当の文明文化というものである。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "戦争にも正義があるし、大義名分があるというようなことは大ウソである。戦争とは人を殺すだけのことでしかないのである。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "人間が戦争を呪うのは当然だ。呪わぬ者は人間ではない。否応なく、いのちを強要される。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "けれども私は「強要せられた」ことを-応忘れる考え方も必要だと思っている。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "凡人も亦かかる崇高な偉業を成就しうるということは、大きな希望ではないか。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "青年諸君よ、この戦争は馬鹿げた茶番にすぎず、そして戦争は永遠に呪うべきものであるが、かつて諸氏の胸に宿った「愛国殉国の情熱」が決して間違ったものではないことに最大の自信を持って欲しい。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "目下の我々のモラルや秩序や理念だけでは、人間は窮すると中世になる。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "自分-人がエライと思うな。オレはエライ、大衆はバカだ、そんなことを言う奴は、私はキライだ。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "大衆は生活している。ウマイモノが食べられない。そんな日本は負けてなくなれ。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "正しい思想というものは、オレと大衆の優劣感のあるところから生れたものではあり得ない。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "人間性は万人に於て変りはない。罪人に於ても聖人に於ても変りはない。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "彼らの政治は「最低生活」の配給へひき下って、そこで競争する以外に手を知らず、品性や秩序も「最低生活」なみのもの、つまり自分のレベルまでひき下げないと統率ができない仕組みであるらしい。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "文化は政治のまきぞへを食ふべき性質のものではない。否、文化はその独自の立場から政治の反省をもとむべき性質のものである。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "自由は地獄の門をくぐる。不安、懊悩、悲痛、慟哭に立たされてゐるものである。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "自由は必ず地獄の中をさまよひ、遂に天国へ到り得ぬ悲しい魂に充たされてゐる。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "真実の自由、自由人は常に反逆人たらざるを得ないものである。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "太宰は口ぐせに、死ぬ死ぬ、と云い、作品の中で自殺し、自殺を暗示していても、それだからホントに死なゝければならぬ、という絶体絶命のものは、どこにも在りはせぬ。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "文学は生きることだよ。見ることではないのだ。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "生きるということは必ずしも行うということでなくともよいかも知れぬ。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "小説なんて、たかが商品であるし、オモチャでもあるし、そして、又、夢を書くことなんだ。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "無数の根から-つの根をとりだすには、御当人の品性や頭の問題が残るだけの話である。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "荷風にはより良く生きようといふ態度がなく、安直に独善をきめこんでゐるのであるから、我を育てた環境のみがなつかしく、生々発展する他の発育に同化する由もない。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "風景も人間も同じやうにたゞ眺めてゐる荷風であり、風景は恋をせず、人間は恋をするだけの違ひであり、人間の眺めに疲れたときに風景の眺めに心をやすめる荷風であつた。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "現代の絵は五千年も昔のお墓の壁画や、なおそれ以上に⽩痴の作品に似ているが、現代⼈の美の好みも美⼈の好みも⽩痴美⼀辺倒的のオモムキがあるようだ。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "真善美の三位⼀体を⼈間そのものに求めると、⽩痴にでも突き当る以外に⼿がなさそうだ。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "しかし⽂学の宿題は⽩痴美を探すことではない。偽悪醜にモミクチャの⼈間をはなれるわけにいかないのである。", Author = "坂口安吾" },
            new Quote { Id = "https://ja.wikiquote.org/wiki/坂口安吾", Text = "空中はたしかに広いものであるが、-尺四方でも表現できるし、オッパイなんてものは、吊り鐘のように大きく書くものではないですよ。", Author = "坂口安吾" },
        };
